import{_ as a,o as n,c as r,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Research on Yuanyuan Manor Tip Money and Themed Earnings","description":"","frontmatter":{"translationSource":{"title":"关于缘缘庄赏钱与主题收益的研究","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=H3BmVSTclK5aAnaHlaRWQI","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-yuanyuan-manor-tip-money-and-themed-earnings"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-yuanyuan-manor-tip-money-and-themed-earnings"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/research-on-yuanyuan-manor-tip-money-and-themed-earnings"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-yuanyuan-manor-tip-money-and-themed-earnings"}]]},"headers":[],"relativePath":"research-on-yuanyuan-manor-tip-money-and-themed-earnings.md","filePath":"logistics/src/page-H3BmVSTclK5aAnaHlaRWQI.md"}'),t={name:"research-on-yuanyuan-manor-tip-money-and-themed-earnings.md"};function i(s,e,l,d,c,p){return n(),r("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="关于缘缘庄赏钱与主题收益的研究" aria-hidden="true"></span><h1 id="research-on-yuanyuan-manor-tip-money-and-themed-earnings" tabindex="-1">Research on Yuanyuan Manor Tip Money and Themed Earnings <a class="header-anchor" href="#research-on-yuanyuan-manor-tip-money-and-themed-earnings" aria-label="Permalink to &quot;Research on Yuanyuan Manor Tip Money and Themed Earnings&quot;">​</a></h1><blockquote><p>Source page ID: <code>H3BmVSTclK5aAnaHlaRWQI</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=H3BmVSTclK5aAnaHlaRWQI" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Data is currently being collected. Once the research is complete, it will be incorporated into the <a href="/endfield-skydoc/yuanyuan-manor-assistant">Yuanyuan Manor Assistant</a> subpage.</p><p>At Yuanyuan Manor, a level-four ordinary guest gives 25% tip money; each popular trend adds 10%; delicacies apparently add about 30%.</p><p>During Full House (满堂彩; provisional rendering), tip money is doubled.</p><p>乐在其中: 10-20 11:58:51</p><p>The most accurate method is to run many trials and calculate the average cost and earnings (?).</p><p>乐在其中: 10-20 11:59:30</p><p>In my experience, the final tip money for the Truly Wholesome theme is usually 64%–71% of the base value.</p><p>Roughly, one guest arrives every 12.5 s on average, and takes about 9 s to place an order.</p></div>',1)])])}const m=a(t,[["render",i]]);export{h as __pageData,m as default};
